select null, t.id, 'builtin', 'Addison disease is caused by:', '["Hypersecretion of cortisol","Hyposecretion of adrenal corticosteroids","Too much thyroid hormone","Too much insulin"]'::jsonb, 1, 'Addison disease (chronic adrenal insufficiency) is hyposecretion of corticosteroids, with low cortisol and reduced aldosterone. Reference: OpenStax Anatomy and Physiology 2e, 17.6 The Adrenal Glands (openstax.org/books/anatomy-and-physiology-2e/pages/17-6-the-adrenal-glands); MedlinePlus Lab Tests, Cortisol Test (medlineplus.gov/lab-tests/cortisol-test); OpenStax Anatomy and Physiology 2e, 26.4 Acid-Base Balance (openstax.org/books/anatomy-and-physiology-2e/pages/26-4-acid-base-balance).', 2, 'verified'
